function distortion_constants_on(points, f):
    K_Lip <- 0
    K_anti <- 0
    for each unordered pair (p, q) in points:
        d  <- dist(p, q)
        df <- dist(f(p), f(q))
        if d > 0:
            K_Lip <- max(K_Lip, df / d)
        if df = 0:
            K_anti <- +infinity        # a collapse: not antilipschitz on s
        else:
            K_anti <- max(K_anti, d / df)
    return (K_Lip, K_anti)

function box_dimension(points, scales):
    xs, ys <- empty lists
    for eps in scales:
        occupied <- empty set
        for (x, y) in points:
            occupied.add( (floor(x/eps), floor(y/eps)) )
        N <- size(occupied)
        if N > 0:
            append log(1/eps) to xs
            append log(N)     to ys
    return least_squares_slope(xs, ys)
